import{_ as a,o,c as i,a0 as n}from"./chunks/framework.BPYRhTv9.js";const u=JSON.parse('{"title":"Known Issues","description":"","frontmatter":{"title":"Known Issues"},"headers":[],"relativePath":"reference/acknowledgements.md","filePath":"reference/acknowledgements.md"}'),r={name:"reference/acknowledgements.md"};function t(s,e,l,d,c,p){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="known-issues" tabindex="-1">Known Issues <a class="header-anchor" href="#known-issues" aria-label="Permalink to &quot;Known Issues&quot;">​</a></h1><p><em>Last updated: Jul 17, 2026</em></p><p>These are bugs and behavior gaps we know about. We list them here because hiding a known issue is worse than naming it.</p><h3 id="webm-not-playable-on-apple-devices" tabindex="-1">WebM not playable on Apple devices <a class="header-anchor" href="#webm-not-playable-on-apple-devices" aria-label="Permalink to &quot;WebM not playable on Apple devices&quot;">​</a></h3><ul><li>Voice-attached cards use the WebM format, which Apple&#39;s QuickTime and iOS Photos app do not play natively.</li><li>On Android and Windows the file opens in the default media player.</li><li>The shared web preview plays the voice in any modern browser, including on Apple devices.</li></ul><p><strong>Workaround:</strong> Open the card via the share link on Apple devices, or download on a non-Apple device first.</p><h3 id="voice-lost-on-png-share-link-upload-fails-silently" tabindex="-1">Voice lost on PNG; share link upload fails silently <a class="header-anchor" href="#voice-lost-on-png-share-link-upload-fails-silently" aria-label="Permalink to &quot;Voice lost on PNG; share link upload fails silently&quot;">​</a></h3><p><strong>PNG downloads do not preserve audio</strong></p><ul><li>PNG is an image-only format and does not support embedded audio.</li><li>Downloading content as a PNG saves only the image.</li><li>Any associated voice recording is not included in the downloaded file.</li></ul><p><strong>Audio upload may fail during share link creation</strong></p><ul><li>When a share link is created, the image is uploaded first.</li><li>The system reports the share operation as successful immediately after the image upload is completed.</li><li>The associated voice recording is uploaded separately in the background.</li><li>If the audio upload fails because of a network interruption, an oversized file, or a temporary server issue, the failure is not reported to the user.</li><li>As a result, the generated share link may contain the image but not the associated voice recording.</li></ul><p><strong>Workaround:</strong> For voice, download the WebM file or use the share link. Verify the voice plays in the preview before sending a share link. The image is always present.</p><h3 id="firefox-cannot-use-browser-transcription" tabindex="-1">Firefox cannot use browser transcription <a class="header-anchor" href="#firefox-cannot-use-browser-transcription" aria-label="Permalink to &quot;Firefox cannot use browser transcription&quot;">​</a></h3><p>Firefox does not support the Web Speech API, which provides browser-native speech-to-text. However, voice recording and server-based transcription via Deepgram work normally in Firefox.</p><ul><li>The Web Speech API (<code>SpeechRecognition</code>) is unavailable in Firefox. This only affects the browser-based fallback transcription path.</li><li>Voice recording (<code>MediaRecorder</code> + <code>getUserMedia</code>) works in Firefox.</li><li>Transcription via the Deepgram server API works in Firefox — it is browser-independent.</li><li>If the Deepgram server is unavailable, Firefox has no fallback transcription method. Chrome, Edge, and Safari can fall back to the Web Speech API in this scenario.</li></ul><p><strong>Workaround:</strong> Use Chrome, Edge, or Safari for voice recording with full browser-based fallback. In Firefox, type your message directly into the text input.</p><h3 id="most-ui-translations-incomplete" tabindex="-1">Most UI translations incomplete <a class="header-anchor" href="#most-ui-translations-incomplete" aria-label="Permalink to &quot;Most UI translations incomplete&quot;">​</a></h3><p>Eleven languages are supported for the card interface, but only English is fully translated. The other ten languages fall back to English for some buttons and messages. The card text itself renders correctly in all languages.</p><p><strong>Workaround:</strong> Use the app in English for the most complete experience. We plan to complete translations in a future update.</p><hr>',20)])])}const f=a(r,[["render",t]]);export{u as __pageData,f as default};
